import {parseCSV} from '../../powertrain/src/maps.mjs';
export function readDefaultCSV(text){const out={};for(const r of parseCSV(text)){if(Object.hasOwn(out,r.key))throw Error('Повторне поле CSV '+r.key);if(!['number','string'].includes(r.type))throw Error('Тип CSV '+r.type);const v=r.type==='number'?Number(r.value):r.value;if(r.type==='number'&&(!r.value.trim()||!Number.isFinite(v)))throw Error('Некоректне число CSV '+r.key);out[r.key]=v;}return out;}
export function readClassCSV(text){const rows=parseCSV(text),seen=new Set();for(const r of rows){if(seen.has(r.id))throw Error('Повторний клас '+r.id);seen.add(r.id);for(const k of ['rated_rpm','sweep_min_rpm','sweep_max_rpm','advice_low_rpm','advice_high_rpm']){r[k]=Number(r[k]);if(!Number.isFinite(r[k])||r[k]<=0)throw Error('Частота класу '+r.id);}if(r.sweep_min_rpm>=r.sweep_max_rpm)throw Error('Порядок частот '+r.id);}return rows;}
export function classProposal(id,bundle,params=null){const c=bundle.engineClasses.find(x=>x.id===id);if(!c)throw Error('Немає профілю класу');const base=bundle.examples.find(e=>e.id===(c.fuel_type==='diesel'?'diesel-design':'kolchin-pfi')).patch;
 const patch={};for(const key of ['fuelType','injection','compression','strokeBore','bmepSeed','intakePressure','intakeTemperature','exhaustPressure','exhaustTemperature','lambda','carbon','hydrogen','oxygen','lhv','fuelDensity','pmaxLimit','vaporization'])patch[key]=base[key]??bundle.defaults[key];
 const fuel=bundle.fuelPresets.find(x=>x.fuelType===c.fuel_type);if(fuel)for(const key of ['carbon','hydrogen','oxygen','lhv','fuelDensity','lambda'])patch[key]=Number(fuel[key]);
 if(c.configuration==='turbo')Object.assign(patch,{injection:'direct',intakePressure:160000,intakeTemperature:330,exhaustPressure:180000});
 for(const row of bundle.classParameters??[])if(row.class_id===id)patch[row.key]=row.type==='number'?Number(row.value):row.value;
 Object.assign(patch,{engineClass:id,ratedSpeed:c.rated_rpm/60,generatorEngineSpeed:Math.min(c.rated_rpm,3500)/60,sweepMinSpeed:c.sweep_min_rpm/60,sweepMaxSpeed:c.sweep_max_rpm/60});if(params?.engineCycle==='two-stroke')patch.scavengePressure=Math.max(bundle.defaults.scavengePressure,patch.exhaustPressure+40000);if(params?.system==='hybrid'&&params.topology==='series'){delete patch.ratedSpeed;patch.generatorEngineSpeed=c.rated_rpm/60;}return {patch,label:c.label_uk+' — початкові проєктні значення',source:c.source_id};}
export function rpmAdvice(p,b){if(p.system==='electric')return {active:false,text:'Частотний діапазон задається характеристикою електромашини.'};const c=b.engineClasses.find(x=>x.id===p.engineClass),n=(p.system==='hybrid'&&p.topology==='series'?p.generatorEngineSpeed:p.ratedSpeed)*60;
 if(!c)return {active:true,text:'Власний частотний режим; клас не підставляє значень.'};const mismatch=c.fuel_type!==p.fuelType,out=n<c.advice_low_rpm||n>c.advice_high_rpm;
 return {active:true,mismatch,out,nominalRPM:n,classId:c.id,source:c.source_id,text:(mismatch?'Клас і тип палива не узгоджені. ':out?'Частота поза допоміжним інтервалом класу; перевірте обґрунтування. ':'')+'Профіль: '+c.label_uk+'. Орієнтовний інтервал '+c.advice_low_rpm+'–'+c.advice_high_rpm+' хв⁻¹; поточне значення '+Math.round(n)+' хв⁻¹. Це не автоматична межа конструкції.'};}

export function recommendedValue(key,p,b){const c=b.engineClasses.find(x=>x.id===p.engineClass),row=b.classParameters?.find(x=>x.class_id===p.engineClass&&x.key===key);if(p.system!=='electric'&&c){if(key==='ratedSpeed'&&!(p.system==='hybrid'&&p.topology==='series'))return c.rated_rpm/60;if(key==='generatorEngineSpeed')return c.rated_rpm/60;if(key==='sweepMinSpeed')return c.sweep_min_rpm/60;if(key==='sweepMaxSpeed')return c.sweep_max_rpm/60;if(row)return row.type==='number'?Number(row.value):row.value;}return b.defaults[key];}
